using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class HistoricalRoadTests
{
    static WorldSession Start(){var s=new WorldSession(HistoricalRoads.Create());Assert.Equal(ResultCode.Accepted,s.Submit(HistoricalRoads.Order(s.DiagnosticSnapshot(),"request:history"),s.Revision).Code);s.AdvanceTo(1);return s;}
    static JourneyLeg Remnant(WorldSession s)=>s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs.Single(l=>l.Edge=="futamura-remnant");
    static HistoricalFeature Supported()=>HistoricalRoads.Remnant with{BuiltYear=1200,YearAttested=true,AlignmentVerified=true,SourceIds=["bunka-futamura"],DistanceBasis="surveyed-historical"};
    [Theory][InlineData("dam")][InlineData("building")][InlineData("expressway")][InlineData("canal")][InlineData("unknown")]
    public void UnsupportedFeaturesCannotEnterHistoricalLayer(string kind)=>Assert.False(HistoricalRoads.CanAdoptAsHistorical(Supported() with{Kind=kind},1560));
    [Theory][InlineData(1604)][InlineData(1610)][InlineData(1977)]
    public void LaterInfrastructureCannotBecomeSengokuInfrastructure(int built)=>Assert.False(HistoricalRoads.CanAdoptAsHistorical(Supported() with{BuiltYear=built},1560));
    [Fact] public void DesignationDateDoesNotStandForHistoricalDate(){Assert.True(HistoricalRoads.CanAdoptAsHistorical(Supported(),1560));Assert.Null(HistoricalRoads.Catalog.Sources.Single(s=>s.Id=="bunka-futamura").PublishedYear);Assert.Contains("2017-04-01",HistoricalRoads.Catalog.Sources.Single(s=>s.Id=="bunka-futamura").Access);}
    [Fact] public void UnknownEraRemovedRoadUnverifiedGeometryOrMissingSourceRejects(){var f=Supported();Assert.False(HistoricalRoads.CanAdoptAsHistorical(f with{BuiltYear=null},1560));Assert.False(HistoricalRoads.CanAdoptAsHistorical(f with{YearAttested=false},1560));Assert.False(HistoricalRoads.CanAdoptAsHistorical(f with{RemovedYear=1560},1560));Assert.False(HistoricalRoads.CanAdoptAsHistorical(f with{AlignmentVerified=false},1560));Assert.False(HistoricalRoads.CanAdoptAsHistorical(f with{SourceIds=["missing"]},1560));Assert.False(HistoricalRoads.CanAdoptAsHistorical(f with{SourceIds=["toyoake-length"]},1560));}
    [Fact] public void RemnantStaysPreviewNotAnInvented1560Survey(){Assert.False(HistoricalRoads.CanAdoptAsHistorical(HistoricalRoads.Remnant,1560));Assert.Equal("published-approximate-preview",HistoricalRoads.DistanceBasis("futamura-remnant"));Assert.Equal("geodesic-estimate",HistoricalRoads.DistanceBasis("nakajima-crossing"));Assert.Equal("synthetic-preview",HistoricalRoads.DistanceBasis("temporary-ford"));}
    [Fact] public void PublishedApproximateLengthIsBoundOnlyToTheExplicitSegment(){var w=HistoricalRoads.Create();Assert.Equal(200000,HistoricalRoads.Edges.Single(e=>e.Id=="futamura-remnant").LengthMm);Assert.Equal(200,BranchRoutes.Duration(["futamura-remnant"],w:w));Assert.Equal(100,BranchRoutes.Duration(["futamura-remnant"],true,w));Assert.Equal(RiverRoads.Edges,HistoricalRoads.Edges.Take(RiverRoads.Edges.Length));Assert.NotEqual(RiverRoads.Version,HistoricalRoads.Version);}
    [Fact] public void QuarterAndHalfPositionsUseTheAdoptedDistanceClock(){var s=Start();var l=Remnant(s);Assert.Equal(200,l.EndAt-l.StartAt);s.AdvanceTo(l.StartAt+100);var nodes=HistoricalRoads.Nodes;var a=nodes.Single(n=>n.Id==l.From).Position;var b=nodes.Single(n=>n.Id==l.To).Position;Assert.Equal(new RoutePoint(a.EastMm+(b.EastMm-a.EastMm)/2,a.NorthMm+(b.NorthMm-a.NorthMm)/2),s.GetBranchView(ContractFixture.Officer).Position);}
    [Theory][InlineData(0)][InlineData(50)][InlineData(100)][InlineData(199)]
    public void SaveRestoresTheSameDistanceGeometryAndCourierState(int progress){var s=Start();var l=Remnant(s);s.AdvanceTo(l.StartAt+progress);var root=Path.Combine(Path.GetTempPath(),"hakutai-history-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,HistoricalRoads.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,1));var host=new WorldSessionHost(new WorldSession(HistoricalRoads.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));host.Current.SetPaused(false);s.AdvanceTo(100000);host.Current.AdvanceTo(100000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Branches),ContractJson.Write(host.Current.DiagnosticSnapshot().Branches));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));}
    [Fact] public void EveryRenderedEdgeHasAnExplicitBasisAndNoPreviewEdgeIsPromoted(){var c=HistoricalRoads.Catalog;Assert.Equal(HistoricalRoads.Edges.Length,c.Bindings.Length);Assert.All(HistoricalRoads.Edges,e=>Assert.False(string.IsNullOrEmpty(HistoricalRoads.DistanceBasis(e.Id))));Assert.All(c.Bindings,b=>Assert.False(b.HistoricalAdoption));Assert.Throws<InvalidOperationException>(()=>HistoricalRoads.DistanceBasis("unknown-road"));}
    [Fact] public void PhysicalReturnCourierUsesTheSame200mRoadAtCourierSpeed(){var s=Start();var leg=Remnant(s);s.AdvanceTo(leg.EndAt+1);var missions=s.DiagnosticSnapshot().Couriers!.Missions;var road=missions.SelectMany(m=>m.Legs).Single(l=>l.Edge=="futamura-remnant");Assert.Equal(200000,road.LengthMm);Assert.Equal(100,road.EndAt-road.StartAt);var m=missions.Single(m=>m.Legs.Contains(road));var p=RegionalCampaign.Position(s.DiagnosticSnapshot(),m,road.StartAt+50);Assert.Equal(new RoutePoint(road.From.EastMm+(road.To.EastMm-road.From.EastMm)/2,road.From.NorthMm+(road.To.NorthMm-road.From.NorthMm)/2),p);}
    [Fact] public void PriorRiverSaveCannotBeLoadedAsThisDefinition(){var s=new WorldSession(RiverRoads.Create());var root=Path.Combine(Path.GetTempPath(),"hakutai-history-old-"+Guid.NewGuid().ToString("N"));new GenerationSaveStore(root,RiverRoads.Create().Definitions).Save(s,"old",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,HistoricalRoads.Create().Definitions).Prepare("old"));}
    [Fact] public void GroundMovementMatchesOneMeterPerSecondInPreview(){var s=Start();var l=Remnant(s);s.AdvanceTo(l.StartAt+10);var a=s.GetBranchView(ContractFixture.Officer);s.AdvanceTo(l.StartAt+11);var b=s.GetBranchView(ContractFixture.Officer);var dx=b.Position.EastMm-a.Position.EastMm;var dn=b.Position.NorthMm-a.Position.NorthMm;Assert.Equal(1000,Math.Sqrt((double)dx*dx+(double)dn*dn));Assert.Equal(1000,b.DistanceMm-a.DistanceMm);}
    [Fact] public void ChangingEvidenceChangesTheDefinitionFingerprint(){var c=HistoricalRoads.Catalog;Assert.NotEqual(ContractJson.CanonicalHash(c),ContractJson.CanonicalHash(c with{RemnantLengthMm=201000}));Assert.NotEqual(ContractJson.CanonicalHash(c),ContractJson.CanonicalHash(c with{WorldYear=1600}));var sources=c.Sources.Select(x=>x with{}).ToArray();sources[0]=sources[0] with{SnapshotSha256=new string('0',64)};Assert.NotEqual(ContractJson.CanonicalHash(c),ContractJson.CanonicalHash(c with{Sources=sources}));Assert.Equal(200000,HistoricalRoads.Catalog.RemnantLengthMm);}
}
